 const status=!bgm.enabled?L('꺼짐','Off'):bgm.status==='error'?L('음원을 불러오지 못했습니다. 껐다 켜서 다시 시도하세요.','Audio could not load. Toggle off/on to retry.'):bgm.title||L('첫 클릭 또는 키 입력 후 재생','Plays after your first click or key press');
