function layers(actor,expression,talking){const states=D.characterLayers[actor];if(!states)return null;let state=expression||'idle';if(state==='default')state='idle';const keys=Object.keys(states);let key=keys.find(k=>k.toLowerCase().endsWith(state.toLowerCase()+'_'+(talking?'talk':'default')))||keys.find(k=>k.endsWith('idle_'+(talking?'talk':'default')))||keys.find(k=>k.endsWith('idle_default'))||keys[0];return states[key];}
function actorHTML(guest,x){return views.actorHTML(guest,x);}
function tagged(raw,count){let used=0,html='',stack=[];const parts=String(raw).split(/(<\/?[a-z]+>)/g);for(const p of parts){const m=p.match(/^<(\/?)([a-z]+)>$/);if(m){const tag=D.tables.text_tags.find(t=>t.tag===m[2]);if(!tag)continue;if(m[1]){if(stack.length){html+='</span>';stack.pop();}}else {html+=`<span style="${tag.kind==='color'?'color:'+tag.value:tag.kind==='size_pct'?'font-size:'+tag.value+'%':''}">`;stack.push(m[2]);}}else{const n=Math.max(0,Math.floor(count)-used);html+=esc(p.slice(0,n));used+=p.length;}}return html+'</span>'.repeat(stack.length);}
function dialogueHTML(){const d=g.currentDialogue();if(!d)return '';const interactive=g.phase!=='general',player=d.actor==='luna';const speaker=player?L('루나','Luna'):g.phase==='general'&&g.seats[g.focus]?.appearance?L('손님','Guest'):g.name(d.actor);return `<div class="dialogue-wrap ${player?'player-speech':'guest-speech'} ${interactive?'':'auto-bubble'}" ${views.dialogueAnchor(d.actor)}><div class="dialogue-box" ${interactive?'data-act="advance" role="button" tabindex="0"':''}><div class="speaker">${esc(speaker)}</div><div class="dialogue-text"><span class="text-measure" aria-hidden="true">${tagged(d.raw||d.text,d.text.length)||'…'}</span><span class="text-ink">${tagged(d.raw||d.text,d.chars)}</span></div><div class="dialogue-next" title="${interactive?(d.chars<d.text.length?L('눌러서 전체 보기','Reveal text'):L('다음 대사 · Enter','Continue · Enter')):L('자동 대사','Auto dialogue')}" aria-label="${interactive?L('다음 대사','Continue'):L('자동 대사','Auto dialogue')}">${interactive?'<span aria-hidden="true">▼</span>':''}</div></div></div>`;}
