function startHTML(){if(ui.minigames)return miniUI.lobbyHTML();if(ui.variant==='gpt')return remixUI.startHTML();const notes={0:L('크리스의 바텐더 튜토리얼 → 포트 첫 주문. 일반 손님 영업은 건너뜁니다.','Chris’s tutorial → Port’s first order. No general guest service.'),1:L('개점 대화 → 일반 손님 4팀 → 포트·아일리 대화와 제조 → 매출 정산.','Opening → 4 general guests → Port and Aili → settlement.'),2:L('일반 손님 영업 데이터만 있습니다. 단골 영업 대본은 비어 있어 정산으로 넘어갑니다.','General guest data is available. The empty regular script is skipped.'),3:L('현재 CSV에 바 영업 대본·손님이 없습니다. 제조 연습으로 3일차 해금 항목을 테스트할 수 있습니다.','No bar content in current CSV. Use practice to test Day 3 unlocks.'),99:L('분기·태그·좌석·동시 입장·재제조 테스트. 모든 재료와 칵테일이 해금됩니다.','QA branches, tags, seats, paired entrance and retries. All recipes unlocked.')};return `<div class="start-screen">${remixUI.tabsHTML()}<div class="intro"><div class="eyebrow">PROJECT L.U.N.A / PLAYTEST</div><h1>${L('오늘 밤도,<br><span>바를 열어볼까요.</span>','Another night.<br><span>Open the bar.</span>')}</h1><p class="lede">${L('한 잔을 만들고, 손님의 이야기를 듣고.<br>바 안에서의 영업 흐름을 직접 확인하는<br>독립 웹 플레이테스트입니다.','Mix a drink, listen to your guests.<br>A standalone playtest of the entire bar loop.')}</p><div class="row wrap"><span class="badge">${L('실제 CSV 대본','Actual CSV scripts')}</span><span class="badge">${L('프로젝트 그래픽','Project artwork')}</span><span class="badge">${L('원본 파일 수정 없음','Source files untouched')}</span></div><div class="source-note">${D.tables.steps.length} ${L('대본 스텝','story steps')} · ${D.tables.barks.length} ${L('상황 대사','barks')} · ${D.tables.cocktails.length} ${L('칵테일','cocktails')}<br>${L('미제공 리소스는 더미로 대체합니다. 엔진 실행본이 아닌 웹 재현판입니다.','Missing assets use placeholders. This is a web recreation, not a Unity build.')}</div></div><div class="start-card"><div class="eyebrow">SESSION SETUP</div><h2 style="margin:15px 0 5px">${L('테스트할 영업을 선택하세요','Choose your session')}</h2><div class="day-list">${[0,1,2,3,99].map(day=>button(day===99?'QA 99':L(day+'일차','Day '+day),'day',`data-id="${day}"`,ui.day===day?'selected':'')).join('')}</div><p class="start-note">${notes[ui.day]}</p>${upkeepInputHTML()}<label for="start-mode">${L('시작 구간','Start at')}</label><select id="start-mode" data-change="mode"><option value="full" ${ui.mode==='full'?'selected':''}>${L('바 내부 전체 흐름','Full bar flow')}</option><option value="general" ${ui.mode==='general'?'selected':''}>${L('일반 손님 영업부터','General guest service')}</option><option value="regular" ${ui.mode==='regular'?'selected':''}>${L('단골 손님 영업부터','Regular guest service')}</option><option value="practice" ${ui.mode==='practice'?'selected':''}>${L('칵테일 제조 연습','Craft practice')}</option></select>${button(L('영업 시작 →','Open the bar →'),'start','','primary')}<div class="spacer"></div><div class="row spread"><small><kbd>F2</kbd> ${L('테스트 도구','Test tools')}</small>${button(L('조작 안내','Controls'),'help','','subtle')}</div></div></div>`;}
function recipeLines(c){return `<ul class="recipe-lines">${g.t.recipes.filter(r=>r.context===c.id).map(r=>`<li><span>${esc(g.name(r.ingredient))}</span><small>${r.qty??'—'} ${r.unit??''} · ${labelType(r.action)}</small></li>`).join('')}</ul><div class="recipe-note">${L('잔','Glass')}: ${esc(g.name(c.glass))}<br>${L('제조 방법','Method')}: ${c.mix} ${c.mix==='build'?L('· 별도 믹스 도구 없음','· no mixing tool'):''}<br>${L('제한 시간','Time limit')}: ${c.time_limit_sec}s</div>`;}
function recipesHTML(){if(remix.active())return remixUI.recipesHTML();const available=g.cocktailsAvailable(),all=g.t.cocktails.filter(c=>g.text(c,'name').toLowerCase().includes(ui.search.toLowerCase()));const peek=g.t.cocktails.find(c=>c.id===ui.peek);return `<aside class="side-panel"><div class="panel-header"><div class="row spread"><h2>${L('칵테일 레시피','Recipe book')}</h2>${button('×','closeRecipe')}</div><small>${L('레시피를 고르면 재료 담기로 이동합니다.','Choose a recipe to prepare ingredients.')}</small><input id="recipe-search" data-input="search" value="${esc(ui.search)}" placeholder="${L('칵테일 검색','Search cocktails')}" aria-label="레시피 검색"></div><div class="recipe-list">${all.map(c=>{const ok=available.some(x=>x.id===c.id);return `<button class="recipe-card ${ok?'':'locked'}" data-act="selectRecipe" data-id="${c.id}" data-hover-recipe="${c.id}" ${ok?'':'disabled'}>${drinkArt(c.id)}<div><strong>${ok?esc(g.text(c,'name')):'???'}</strong><small>${ok?`${c.mix.toUpperCase()} · ${money(c.price)}`:L(c.unlock_day+'일차 해금','Day '+c.unlock_day+' unlock')}</small></div><span>${ok?'→':'◇'}</span></button>`;}).join('')}</div><div class="panel-header"><small>${available.length} / ${g.t.cocktails.length} ${L('해금 · 바 시간 정지','unlocked · bar time paused')}</small></div></aside>${peek&&available.includes(peek)?`<section class="recipe-peek">${drinkArt(peek.id)}<h2>${esc(g.name(peek.id))}</h2>${recipeLines(peek)}<div class="divider"></div><p class="recipe-note">${esc(g.text(peek,'recipe_desc'))}</p></section>`:''}`;}
