function gimmickHTML(){const s=g.gimmick;if(!s)return '';if(s.fluid)return pourView.html(s);if(['stir','shake'].includes(s.type))return views.mixHTML(s);const t=s.type;let body='';
 if(t==='open'){const radius=Math.max(12,g.c('open_start_radius_px',165)-(g.c('open_start_radius_px',165)-g.c('open_target_radius_px',44))*s.beatTime/g.c('open_approach_sec',1.6));body=`<div class="gimmick-instruction">${L('줄어드는 원이 초록 원에 맞으면 누르세요.','Press when the shrinking ring meets the green ring.')}</div><div class="open-ring">${itemArt(s.ingredient)}<div class="target-ring"></div><div class="ring" style="width:${radius*1.68}px;height:${radius*1.68}px"></div></div><div class="stack-count">${L('실패','Misses')} ${s.failures} · ${L('실패당 15점 감점','−15 points per miss')}</div><div class="stir-message">${s.message}</div>${button(s.completed?'OPEN':s.started?L('병따기','Open')+' <kbd>Space</kbd>':L('시작','Start'),'gimmickInput',s.completed?'disabled':'','primary hold-button')}`;}
 else body=`<div class="critical">${L('현재 운영 데이터 범위 밖의 기믹','Gimmick outside the imported production scope')}: ${esc(t)}</div>`;
 return `<div class="craft-screen" ${remix.active()&&t==='open'?'data-auto-gimmick="true"':''}><div class="craft-top"><h2>${labelType(t)} <small>${s.ingredient?' / '+esc(g.name(s.ingredient)):''}</small></h2><span class="badge">${g.minigame?L('단독 연습','Single skill'):g.craft.index+1+' / '+g.craft.queue.length} · ${esc(g.name(g.craft.actual.selected))}</span>${g.minigame?button(L('기믹 선택','Choose a minigame'),'miniExit','','subtle'):button(L('레시피','Recipe'),'craftRecipe','','subtle')}</div><div class="gimmick-body" style="background-image:url('${a(t==='shake'?'gimmick_shake':t==='stir'?'gimmick_stir':'gimmick')}')"><div class="gimmick-content">${body}</div></div><div class="gimmick-footer"><div><p>${L('수동 기믹 시간','Active craft time')} <span class="num">${g.craft.elapsed.toFixed(1)}s</span>${g.minigame?'':' / '+g.cocktail(g.craft.actual.selected).time_limit_sec+'s'}</p><small>${L('준비·화면 전환 시간은 포함하지 않습니다.','Preparation and transitions are excluded.')}</small></div>${button(g.minigame?L('결과 보기 →','View result →'):s.completed?L('다음 →','Next →'):L('현재 기믹 마치기 →','Finish this step →'),'endGimmick',!s.started||g.minigame&&!s.completed?'disabled':'','primary')}</div></div>`;}
function resultHTML(){if(remix.active())return remixUI.resultHTML();const r=g.result;const labels={gimmick:L('기믹 오차','Gimmick errors'),glass:L('잔 불일치','Wrong glass'),tool:L('도구 누락·불일치','Missing / wrong tool'),missing:L('재료 누락','Missing ingredients'),extra:L('추가 재료','Extra ingredients'),overtime:L('제조시간 초과','Overtime')};return `<div class="craft-screen"><div class="craft-top"><h2>${L('제조 완료','Craft complete')}</h2><span class="badge">${L('아직 주문과 연결되지 않은 제조 결과','Craft result · not yet bound to an order')}</span></div><div class="result-body"><div class="result-card"><div class="result-art">${drinkArt(r.selected)}<div class="grade">${r.grade}</div><small>${r.score.toFixed(1)} / 100</small>${r.debug?'<p class="dummy-tag">TEST OVERRIDE</p>':''}</div><div><div class="eyebrow">CRAFT RESULT</div><h2 style="margin-top:12px">${esc(g.name(r.selected))}</h2><table class="result-table">${Object.entries(r.penalties).map(([k,v])=>`<tr><td>${labels[k]}</td><td class="${v?'bad':'muted'}">−${v.toFixed(1)}</td></tr>`).join('')}</table><p class="recipe-note">${L('주문 일치 여부와 최종 등급은 코스터에 제공할 때 결정됩니다.','Order matching and the final grade are determined at serving.')}</p>${r.missingCore.length?`<p class="bad">${L('핵심 재료 누락','Missing core ingredients')}: ${r.missingCore.map(id=>esc(g.name(id))).join(', ')}</p>`:''}<div class="row">${button(L('제공하기 →','Offer drink →'),'offer','','primary grow')}${button(L('버리기','Discard'),'discard','','danger')}</div></div></div></div></div>`;}
function totalsHTML(){const t=g.totals();return `<div class="totals">${[['sale',L('판매','Sales')],['tip',L('팁','Tips')],['refund',remix.active()?L('배상','Compensation'):L('환불','Refunds')],['net',L('합계','Net')]].map(([k,v])=>`<div><small>${v}</small><strong>${fmt(t[k])}</strong></div>`).join('')}</div>`;}
function salesHTML(){return totalsHTML()+`<div class="table-scroll"><table class="data-table"><thead><tr><th>${L('제공한 칵테일','Drink')}</th><th>${L('최종 등급','Final grade')}</th><th>${L('합계','Net')}</th></tr></thead><tbody>${g.transactions.map(t=>`<tr><td>${esc(g.name(t.served))}</td><td>${t.grade.toUpperCase()}${!t.match?' · '+L('주문 불일치','Wrong order'):''}</td><td>${money(t.net)}</td></tr>`).join('')||`<tr><td colspan="3" class="empty">${L('아직 정산된 주문이 없습니다.','No settled orders yet.')}</td></tr>`}</tbody></table></div>`;}
function modal(title,body,wide=false,close=true){return `<div class="modal-backdrop"><section class="modal ${wide?'wide':''}"><div class="modal-title"><h2>${title}</h2>${close?button('×','closeOverlay'):''}</div>${body}</section></div>`;}
// Explicit web adapters only. These do not define or rewrite the production CSV contract.
const DOSSIER_ROSTER=['chris','port','aili','bubi','shiba','samho','tom'];
const DOSSIER_MET_FLAGS={chris:'chris_met',port:'port_met',aili:'aili_met',bubi:'bubi_met',shiba:'shiba_met',samho:'samho_met',tom:'tom_met'};
function dossierState(id){
 const preview=ui.dossierPreview?.id===id?ui.dossierPreview.stage:null;
 const met=preview!==null?preview>0:!!g.progress.flags[DOSSIER_MET_FLAGS[id]];
 const character=g.t.characters.find(c=>c.id===id),aff=Number(g.progress.affinity[id]||0);
 // Shiba's affinity feature is unconfirmed: live mode exposes stage 1 only.
 const stage=preview!==null?preview:!met?0:character?.affinity===false?1:aff>=30?3:aff>=10?2:1;
 return {met,stage,preview:preview!==null};
}
function dossierPortrait(id){
 const keys=layers(id,'idle',false),sample=keys?.length?D.assets[keys[0]]:null;
 return '<div class="dossier-portrait" role="img" aria-label="'+esc(g.name(id))+'"><div class="portrait-canvas" style="aspect-ratio:'+ (sample?(sample.w/(sample.frames||1))+'/'+sample.h:'1/1')+'">'+(keys?.length?keys.map(k=>{const v=D.assets[k];return '<span style="background-image:url('+v.src+');background-size:'+((v.frames||1)*100)+'% 100%"></span>';}).join(''):'<div class="portrait-placeholder"><span>◇</span><small>'+L('프로필 이미지 준비 중','Portrait pending')+'</small></div>')+'</div></div>';
}
function affinityBar(stage){return '<div class="affinity-bar" role="img" aria-label="'+L('호감도 '+stage+'단계','Affinity stage '+stage)+'">'+[1,2,3].map(n=>'<i class="'+(n<=stage?'filled':'')+'"></i>').join('')+'</div>';}
function dossierSection(ko,en,unlocked,content){return '<section class="profile-section '+(unlocked?'':'locked')+'"><h3>'+L(ko,en)+'</h3>'+(unlocked?content:'<div class="profile-locked" aria-label="'+L('미해금 정보','Locked information')+'">???</div>')+'</section>';}
function dossierDetailHTML(id){
 const {stage}=dossierState(id),pending='<p class="profile-pending">'+L('원고 연결 대기','Copy not connected yet')+'</p>';
 const basic='<dl class="profile-facts">'+[['나이','Age'],['신체','Height / weight'],['직업','Occupation'],['거주지','Residence']].map(([ko,en])=>'<div><dt>'+L(ko,en)+'</dt><dd>—</dd></div>').join('')+'</dl>';
 return '<div class="dossier-detail-backdrop"><section class="dossier-detail" role="dialog" aria-modal="true" aria-labelledby="profile-name"><aside class="profile-left">'+dossierPortrait(id)+'<div class="profile-affinity"><span>'+L('호감도','Affinity')+'</span>'+affinityBar(stage)+'</div></aside><div class="profile-right"><header><h2 id="profile-name">'+esc(g.name(id))+'</h2></header><div class="profile-body" tabindex="0">'+dossierSection('기본 정보','Basic information',true,basic)+dossierSection('루나에 대한 생각','Thoughts about Luna',true,pending)+dossierSection('좋아하는 칵테일','Favorite cocktail',stage>=2,pending)+dossierSection('관찰 내용','Observations',true,'<p class="profile-pending" data-observation-stage="'+stage+'">'+L('관찰 '+stage+' 원고 연결 대기','Stage '+stage+' observation not connected yet')+'</p>')+dossierSection('과거사','Background',stage>=3,pending)+'<p class="profile-data-note">'+L('새 UI 항목과 기존 수첩 원고의 대응은 아직 미확정입니다. 인물 설정을 임의로 채우지 않았습니다.','The new UI fields have not been mapped to existing dossier copy. Character details have not been invented.')+'</p></div></div><footer>'+button('<kbd>Esc</kbd> '+L('목록으로','Back to list'),'dossierBack','','subtle')+'</footer></section></div>';
}
function dossierHTML(){
 const detail=ui.dossierDetail&&dossierState(ui.dossierDetail).met?ui.dossierDetail:null;
 return '<section class="dossier-screen" role="dialog" aria-modal="true" aria-labelledby="dossier-title"><div class="dossier-list-shell" '+(detail?'inert aria-hidden="true"':'')+'><header class="dossier-header"><div class="dossier-heading"><span></span><h2 id="dossier-title">'+L('인물 정보','Guest profiles')+'</h2><span></span></div><div class="dossier-money">'+money(g.progress.money)+'</div></header><div class="dossier-list-scroll" tabindex="0"><div class="dossier-grid">'+DOSSIER_ROSTER.map(id=>{const st=dossierState(id);return '<button class="guest-card '+(!st.met?'unmet':ui.dossier===id?'selected':'')+'" data-act="dossier" data-id="'+id+'" '+(!st.met?'disabled aria-label="'+L('아직 만나지 않은 손님','Guest not yet met')+'"':'aria-label="'+esc(g.name(id))+'"')+'>'+(st.met?dossierPortrait(id)+'<div class="guest-card-caption"><span>'+esc(g.name(id))+'</span>'+affinityBar(st.stage)+'</div>':'<span aria-hidden="true">?</span>')+'</button>';}).join('')+'</div></div><footer class="dossier-footer"><p>'+L('손님을 선택하면 자세한 정보를 확인할 수 있습니다.','Select a guest to view their details.')+'</p>'+button('<kbd>Esc</kbd> '+L('닫기','Close'),'dossierBack','','subtle')+'</footer></div>'+ (ui.dossierPreview?'<div class="dossier-preview-badge">'+L('UI 상태 미리보기 · 진행 데이터 변경 없음','UI preview · progress is unchanged')+'</div>':'')+(detail?dossierDetailHTML(detail):'')+'</section>';
}
function dossierInspectorHTML(){return '<label>'+L('단골 정보 UI 검수','Guest profile UI test')+'</label><select data-change="dossierTestActor">'+DOSSIER_ROSTER.map(id=>'<option value="'+id+'" '+(ui.dossierTestActor===id?'selected':'')+'>'+esc(g.name(id))+'</option>').join('')+'</select><div class="row wrap">'+[0,1,2,3].map(stage=>button(stage?L(stage+'단계', 'Stage '+stage):L('미만남','Unmet'),'dossierPreview','data-id="'+stage+'"')).join('')+'</div>'+button(L('실제 진행 상태로 보기','Use live progress'),'dossierLive')+'<small>'+L('미리보기는 플래그·호감도를 바꾸지 않습니다. 원고 매핑·시바의 추가 단계·호감도 하락 시 재잠금은 미확정입니다.','Preview never changes flags or affinity. Copy mapping, Shiba’s higher stages and re-locking policy remain unconfirmed.')+'</small>';}
function dossierBack(){
 if(ui.dossierDetail){const id=ui.dossierDetail;ui.dossierDetail=null;render(true);root.querySelector('.guest-card[data-id="'+id+'"]')?.focus({preventScroll:true});}
 else {g.overlay=null;ui.dossierPreview=null;render(true);root.querySelector('[data-act="service"]')?.focus({preventScroll:true});}
}
function helpHTML(){return `<div class="help-grid"><section><h3>${L('일반 손님 영업','General guests')}</h3><p><kbd>A</kbd> <kbd>D</kbd> / ← → ${L('좌석 이동','Move seats')}</p><p><kbd>Space</kbd> ${L('앞자리 손님에게 코스터 제공','Give a coaster to the focused guest')}</p><p><kbd>E</kbd> ${L('주문 되묻기 · 인내심 10% 차감','Ask again · patience −10%')}</p><p>${L('대사는 현재 보고 있는 좌석에서 자동 진행됩니다.','Barks advance automatically at the focused seat.')}</p></section><section><h3>${L('단골 손님 영업','Regular guests')}</h3><p><kbd>Enter</kbd> / <kbd>Space</kbd> ${L('다음 대사','Next dialogue')}</p><p>${L('주문 대사가 끝나면 코스터가 자동으로 놓입니다.','Coasters appear after the order dialogue.')}</p><p>${L('선택지는 ↑/↓ 이동, Enter/Space 확정 또는 클릭. 제조는 화면 버튼을 사용합니다.','Choices: ↑/↓ to move, Enter/Space to confirm, or click. Use on-screen buttons for crafting.')}</p></section><section><h3>${L('제조·제공','Craft and serve')}</h3><p>${L('레시피 → 잔·도구·재료 → 기믹 → 제공하기 → 잔을 코스터로 드래그','Recipe → glass / tool / ingredients → gimmicks → offer → drag onto a coaster')}</p><p>${L('빌드는 도구를 선택하지 않습니다. 메뉴·제조 중에는 바 시간이 멈춥니다.','Build uses no mixing tool. Menus and crafting pause bar time.')}</p></section><section><h3>${L('메뉴·테스트','Menus and testing')}</h3><p><kbd>Tab</kbd> ${L('왼쪽 서비스 패널 · 레시피 / 매출 / 단골 정보','Left service panel · recipes / sales / guest profiles')}</p><p><kbd>F2</kbd> ${L('상태·타이머·분기·로그 확인','Inspect state, timers, branches and logs')}</p><p><kbd>Y</kbd> ${L('대사 기록 열기 / 닫기','Open / close dialogue history')}</p><p><kbd>Esc</kbd> ${L('옵션 · 일시정지 / 열린 메뉴 닫기','Options · pause / close the open menu')}</p><p>${L('F2 안의 정답 채우기·등급 강제는 검수 전용입니다.','Recipe fill and grade overrides in F2 are testing tools only.')}</p></section></div><div class="divider"></div><p class="recipe-note">${L('실제 CSV의 0·1·99일차 대본을 사용합니다. 2·3일차의 비어 있는 대본은 만들어 넣지 않았습니다. 일부 그래픽과 효과음은 더미이며, 쉐이킹은 브라우저용 타이밍 조작으로 재현했습니다.','Uses the actual Day 0, 1 and 99 scripts. Empty Day 2/3 scripts are not invented. Missing artwork/audio uses placeholders; shaking uses a browser timing interaction.')}</p>`;}
function serviceHTML(){return `<div class="service-layer"><button class="service-scrim" data-act="service" aria-label="${L('서비스 패널 닫기','Close service panel')}"></button><aside id="service-panel" class="service-panel" role="dialog" aria-modal="true" aria-labelledby="service-title">
 <header><h2 id="service-title">${L('서비스 패널','Service panel')}</h2>${button('×','service','aria-label="'+L('서비스 패널 닫기','Close service panel')+'"')}</header>
 <div class="service-actions">${button('<span>▤</span>'+L('칵테일 레시피 보기','Cocktail recipes'),'recipes')}${button('<span>▥</span>'+L('매출 현황 보기','Sales summary'),'sales')}${button('<span>♙</span>'+L('단골 손님 정보 보기','Regular guest profiles'),'dossierOpen')}</div>
 <p>${L('패널을 열면 영업 시간이 멈춥니다.','Service time is paused while this panel is open.')}</p><small><kbd>Tab</kbd> / <kbd>Esc</kbd> ${L('닫기','Close')}</small></aside></div>`;}
function toggleService(){
 if(g.overlay==='service'){g.overlay=null;render(true);root.querySelector('[data-act="service"]')?.focus({preventScroll:true});return;}
 if(g.screen!=='bar'||g.phase==='ready'||g.finished||g.isPaused()||ui.drag)return;
 ui.readSkip=false;ui.inspector=false;show('service');root.querySelector('#service-panel [data-act="recipes"]')?.focus({preventScroll:true});
}
function overlayHTML(){if(!g.overlay)return '';if(ui.minigames&&g.overlay==='help')return modal(L('기믹 미니게임 조작','Minigame controls'),miniUI.helpHTML(),true);if(g.overlay==='miniExit')return modal(L('기믹 선택으로 돌아갈까요?','Return to minigame selection?'),`<p>${L('현재 연습은 종료됩니다. 같은 기믹은 언제든 다시 시작할 수 있어요.','This attempt will end. You can replay any skill at any time.')}</p><div class="row">${button(L('계속 연습','Keep practicing'),'closeOverlay')}${button(L('기믹 선택','Choose a minigame'),'miniLobby','','primary')}</div>`);if(ui.minigames&&g.overlay==='settings')return modal(L('옵션 · 일시정지','Options · paused'),`<div class="settings-row"><span>${L('언어','Language')}</span><select data-change="language"><option value="ko" ${g.lang==='ko'?'selected':''}>한국어</option><option value="en" ${g.lang==='en'?'selected':''}>English</option></select></div>${bgmSettingsHTML()}<p class="recipe-note">${L('옵션이 열린 동안 기믹 시간이 멈춥니다. 영업·칵테일 기록과는 별개인 단독 연습입니다.','The minigame is paused while options are open. Practice is separate from service and cocktail records.')}</p><div class="row wrap">${button(L('기믹 선택으로','Minigame selection'),g.minigame?'miniExit':'miniLobby')}${button(L('영업 시작 화면','Bar setup'),'miniBar')}${siteHome?'<a class="site-home" href="../index.html">← '+L('메인 로비','Main lobby')+'</a>':''}</div>`);if(g.overlay==='remixGoals')return modal(L('이번 영업의 목표','Shift goals'),remixUI.goalsHTML());if(g.overlay==='service')return serviceHTML();if(g.overlay==='help')return modal(L('조작 안내','Controls'),remix.active()?remixUI.helpHTML():helpHTML(),true);if(g.overlay==='sales')return modal(L('매출 현황','Sales'),salesHTML(),true);if(g.overlay==='dossier')return dossierHTML();if(g.overlay==='history')return modal(L('대사 기록','Dialogue history'),g.history.slice(-150).map(h=>`<div class="history-line"><b>${esc(g.name(h.actor))}</b>${esc(h.text)}</div>`).join('')||'<div class="empty">'+L('아직 대사가 없습니다.','No dialogue yet.')+'</div>');if(g.overlay==='recipe')return modal(esc(g.name(g.craft.actual.selected)),recipeLines(g.cocktail(g.craft.actual.selected)));if(g.overlay==='restart')return modal(L('테스트를 다시 시작할까요?','Restart the test?'),`<p>${L('현재 영업 상태는 초기화됩니다. 필요한 경우 로그를 먼저 내보내세요.','Current session state will be reset. Export logs first if needed.')}</p><div class="row">${button(L('로그 내보내기','Export logs'),'export')}${button(L('일차 선택으로','Session setup'),'setup','','primary')}</div>`);if(g.overlay==='settings')return modal(L('설정','Settings'),`<div class="settings-row"><span>${L('언어 · 변경 후 새 대사부터','Language · from next dialogue')}</span><select data-change="language"><option value="ko" ${g.lang==='ko'?'selected':''}>한국어</option><option value="en" ${g.lang==='en'?'selected':''}>English</option></select></div><div class="settings-row"><span>${L('대사 출력 속도','Text speed')}</span><select data-change="dialogSpeed">${[1,2,4].map(v=>`<option value="${v}" ${g.dialogSpeed===v?'selected':''}>×${v}</option>`).join('')}</select></div><div class="settings-row"><span>${L('단골 대사 자동 넘김','Auto-advance regular dialogue')}</span>${button(ui.auto?L('켜짐','On'):L('꺼짐','Off'),'auto')}</div>${bgmSettingsHTML()}<div class="settings-row"><span>${L('더미 효과음','Placeholder audio')}</span>${button(ui.sound?L('켜짐','On'):L('꺼짐','Off'),'sound')}</div><div class="divider"></div><p class="recipe-note">${L('게임 저장 기능은 없습니다. 이 페이지는 바 내부 테스트만 다룹니다. 설정 메뉴를 열면 영업과 제조 시간이 모두 멈춥니다.','No game saves here: this page tests the bar interior only. Settings pause both service and crafting timers.')}</p><div class="row wrap">${button(L('일차 / 시작 구간 변경','Change day / start phase'),'restart','','danger')}${siteHome?'<a class="site-home" href="../index.html">← '+L('로비로 돌아가기','Return to lobby')+'</a>':''}</div>`);return '';}
function upkeepInspectorHTML(){
 const info=g.upkeepInfo();return `<label>${L('하루 정산 테스트','Daily settlement test')}</label><div class="inspect-row">${L('이번 유지비','Upkeep')}: ${money(info.amount)} · ${info.source==='web_test'?L('웹 테스트값','Test override'):L('일차 기본값','Day default')}</div><div class="row upkeep-editor"><input type="number" min="0" step="1" data-input="upkeep" value="${esc(ui.upkeep)}" placeholder="${L('빈칸 = 데이터값','Blank = data')}" aria-label="유지비 테스트값 수정" ${g.finished?'disabled':''}>${button(L('적용','Apply'),'applyUpkeep',g.finished?'disabled':'')}</div>${button(L('지금 영업 끝내고 정산 보기','End service now and show settlement'),'debugEndDay',g.finished||g.phase==='ready'?'disabled':'','danger')}<small>${L('검수용 조기 종료입니다. 미제공 주문은 매출에 넣지 않습니다.','Test-only early ending. Unserved orders are not counted.')}</small>`;
}
